   230	/**
   231	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
   232	 * high-season nights; the rate plan then decides the price from those nights. Money is rounded to cents
   233	 * (half-even) at every step.
   234	 */
   235	public final class PriceCalculator {
   236	
   237	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
   238	
   239	    private final RatePlans ratePlans;
   240	
   241	    public PriceCalculator(RatePlans ratePlans) {
   242	        this.ratePlans = ratePlans;
   243	    }
   244	
   245	    /** Throws INVALID_REQUEST when the rate plan does not allow this stay. */
   246	    public Price calculate(Room room, NewReservation request) {
   247	        RatePlanPolicy plan = ratePlans.policyFor(request.ratePlan());
   248	        plan.validate(room, request);
   249	        return plan.price(room, request, nightlyCharges(room, request.checkIn(), request.checkOut()));
   250	    }
   251	
   252	    NightlyCharges nightlyCharges(Room room, LocalDate checkIn, LocalDate checkOut) {
   253	        int nights = 0;
   254	        BigDecimal subtotal = cents(BigDecimal.ZERO);
   255	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
   256	            subtotal = subtotal.add(nightPrice(room, night));
   257	            nights++;
   258	        }
   259	        return new NightlyCharges(nights, subtotal);
   260	    }
   261	
   262	    BigDecimal nightPrice(Room room, LocalDate night) {
   263	        BigDecimal nightlyRate = room.nightlyRate();
   264	        if (isHighSeason(night)) {
   265	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
   266	        }
   267	        return cents(nightlyRate);
   268	    }
   269	
   270	    /** High season: from December 15 to the end of February, and the whole of July. */
   271	    static boolean isHighSeason(LocalDate date) {
   272	        Month month = date.getMonth();
   273	        return month == Month.JANUARY
   274	                || month == Month.FEBRUARY
   275	                || month == Month.JULY
   276	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
   277	    }
   278	
   279	    static BigDecimal cents(BigDecimal value) {
   280	        return value.setScale(2, RoundingMode.HALF_EVEN);
   281	    }
   282	}

